from rdkit import Chem
from rdkit.Chem import AllChem
import tmap as tm
fp_length = 512
#seed = 420
minhash = tm.Minhash(fp_length)

### use this, as this is compatible with AbbVie TMAP stuff provided by Sven
def get_shingles(smiles):

    qry_shingles = set()
    mol = Chem.MolFromSmiles(smiles)
    if mol is None:
        return None


    for atm_idx in range(mol.GetNumAtoms()):
        for N in range(1,4):
            bonds = AllChem.FindAtomEnvironmentOfRadiusN(mol, N, atm_idx)

            if not bonds:
                break
            atoms = set()
            for bond_id in bonds:
                bond = mol.GetBondWithIdx(bond_id)
                atoms.add(bond.GetBeginAtomIdx())
                atoms.add(bond.GetEndAtomIdx())

            new_shingle = Chem.rdmolfiles.MolFragmentToSmiles(mol,list(atoms),bonds,0,0,False,False,atm_idx,True,False,False)

            qry_shingles.add(new_shingle)

    return qry_shingles

def calc_mhfp(smiles):
    # skip missing or non‐string
    if not isinstance(smiles, str):
        return None
    shingles = get_shingles(smiles)
    if shingles is None or len(shingles) == 0:
        return None
    return minhash.from_string_array(list(shingles))

